 if not matches:raise RuntimeError('Missing inherited source '+key)
 f=matches[0];records.append(dict(id=key,path=str(f.relative_to(root)),sha256=sha(f),read_scope=anchors,source_limit=limit,status='inherited inspected evidence; McCarthy completed this work unit'))
