# Verify downloaded Git blob bytes against official pinned tree, not names alone.
code=[]
for tree,pairs in [('maliar-tree.json',[('README.md','maliar-readme.md'),('LICENSE','maliar-license'),('code/python/Main_KS.ipynb','maliar-notebook.ipynb')]),('smc-code-tree.json',[(x,'smc-'+x.replace('/','_')) for x in ['README.md','LICENSE','particles/smc_samplers.py','particles/mcmc.py','book/smc2/smc2_stochvol_leverage.py']])]:
 j=json.loads((p/'sources'/tree).read_text());lookup={x['path']:x['sha'] for x in j['tree']}
 for path,local in pairs:
  b=(p/'sources'/local).read_bytes();actual=hashlib.sha1(b'blob '+str(len(b)).encode()+bytes([0])+b).hexdigest();ok=actual==lookup[path];code.append(dict(path=path,local=local,git_blob=actual,expected=lookup[path],sha256=hashlib.sha256(b).hexdigest(),passed=ok));assert ok
write('code-integrity.json',dict(status='PASS',records=code))
